38	  /*
39	   * These constants are copied from org.apache.avro.LogicalTypes
40	   */
41	  private static final String DECIMAL = "decimal";
42	  private static final String UUID = "uuid";
43	  private static final String DATE = "date";
44	  private static final String TIME_MILLIS = "time-millis";
45	  private static final String TIME_MICROS = "time-micros";
46	  private static final String TIMESTAMP_MILLIS = "timestamp-millis";
