54	    CONVERSION_MAP.put(TIME_MILLIS, new TimeConversions.TimeMillisConversion());
55	    CONVERSION_MAP.put(TIME_MICROS, new TimeConversions.TimeMicrosConversion());
56	    CONVERSION_MAP.put(TIMESTAMP_MILLIS, new TimeConversions.TimestampMillisConversion());
57	    CONVERSION_MAP.put(TIMESTAMP_MICROS, new TimeConversions.TimestampMicrosConversion());
58	  }
