152	  /**
153	   * Applies the logical type conversion to the given Avro record field. If there isn't a logical
154	   * type for the value then the value is returned unchanged. If there is a logical type associated
155	   * to the field but no Avro conversion is known for the type then the value is returned unchanged.
156	   *
157	   * @param field Avro field spec
158	   * @param value Value of the field
159	   * @return Converted value as per the logical type in the spec, or the unchanged value if a
160	   *     logical type or conversion can't be found.
161	   */
162	  public static Object applyLogicalType(Schema.Field field, Object value) {
163	    if (field == null || field.schema() == null) {
164	      return value;
165	    }
166	    // Choose the non-null schema when the field schema is represented as union schema. Only then, the avro library
167	    // is able to determine the correct logical type for the field.
168	    Schema fieldSchema = field.schema();
169	    if (fieldSchema.isUnion()) {
170	      List<Schema> fieldSchemas = fieldSchema.getTypes();
171	      for (Schema curSchema: fieldSchemas) {
172	        if (curSchema.getLogicalType() != null) {
173	          fieldSchema = curSchema;
174	          break;
175	        }
176	      }
177	    }
178	    LogicalType logicalType = LogicalTypes.fromSchemaIgnoreInvalid(fieldSchema);
179	    if (logicalType == null) {
180	      return value;
181	    }
182	    Conversion<?> conversion = AvroSchemaUtil.findConversionFor(logicalType.getName());
183	    if (conversion == null) {
184	      return value;
185	    }
186	    return Conversions.convertToLogicalType(value, fieldSchema, logicalType, conversion);
187	  }
188	}
