87	  @Test
88	  public void testLogicalTypesWithUnionSchema() {
89	    String valString1 = "125.24350000";
90	    ByteBuffer amount1 = decimalToBytes(new BigDecimal(valString1), 8);
91	    // union schema for the logical field with "null" and "decimal" as types
92	    String fieldSchema1 = "{\"type\":\"record\",\"name\":\"Event\",\"fields\":[{\"name\":\"amount\","
93	        + "\"type\":[\"null\",{\"type\":\"bytes\",\"logicalType\":\"decimal\",\"precision\":20,\"scale\":8}]}]}";
94	    Schema schema1 = new Schema.Parser().parse(fieldSchema1);
95	    Object result1 = AvroSchemaUtil.applyLogicalType(schema1.getField("amount"), amount1);
96	    Assert.assertTrue(result1 instanceof BigDecimal);
97	    Assert.assertEquals(valString1, ((BigDecimal) result1).toPlainString());
98	
99	    String valString2 = "125.53172";
100	    ByteBuffer amount2 = decimalToBytes(new BigDecimal(valString2), 5);
101	    // "null" not present within the union schema for the logical field amount
102	    String fieldSchema2 = "{\"type\":\"record\",\"name\":\"Event\",\"fields\":[{\"name\":\"amount\","
103	        + "\"type\":[{\"type\":\"bytes\",\"logicalType\":\"decimal\",\"precision\":20,\"scale\":5}]}]}";
104	    Schema schema2 = new Schema.Parser().parse(fieldSchema2);
105	    Object result2 = AvroSchemaUtil.applyLogicalType(schema2.getField("amount"), amount2);
106	    Assert.assertTrue(result2 instanceof BigDecimal);
107	    Assert.assertEquals(valString2, ((BigDecimal) result2).toPlainString());
108	
109	    String valString3 = "211.53172864999";
110	    ByteBuffer amount3 = decimalToBytes(new BigDecimal(valString3), 11);
111	    // "null" present at the second position within the union schema for the logical field amount
112	    String fieldSchema3 = "{\"type\":\"record\",\"name\":\"Event\",\"fields\":[{\"name\":\"amount\","
113	        + "\"type\":[{\"type\":\"bytes\",\"logicalType\":\"decimal\",\"precision\":20,\"scale\":11}, \"null\"]}]}";
114	    Schema schema3 = new Schema.Parser().parse(fieldSchema3);
115	    Object result3 = AvroSchemaUtil.applyLogicalType(schema3.getField("amount"), amount3);
116	    Assert.assertTrue(result3 instanceof BigDecimal);
117	    Assert.assertEquals(valString3, ((BigDecimal) result3).toPlainString());
118	  }
119	
120	  private static ByteBuffer decimalToBytes(BigDecimal decimal, int scale) {
121	    BigDecimal scaledValue = decimal.setScale(scale, RoundingMode.DOWN);
122	    byte[] unscaledBytes = scaledValue.unscaledValue().toByteArray();
123	    return ByteBuffer.wrap(unscaledBytes);
124	  }
125	}
